def solve(tokens):
    """Evaluate Reverse Polish Notation expression.
    tokens: list of strings representing integers or operators + - * /
    Returns integer result with division truncating toward zero.
    """
    stack = []
    for t in tokens:
        if t not in {"+", "-", "*", "/"}:
            stack.append(int(t))
        else:
            b = stack.pop()
            a = stack.pop()
            if t == '+':
                stack.append(a + b)
            elif t == '-':
                stack.append(a - b)
            elif t == '*':
                stack.append(a * b)
            else:  # division
                # Python division truncates toward negative infinity, need toward zero
                if a * b < 0:
                    stack.append(- (abs(a) // abs(b)))
                else:
                    stack.append(a // b)
    return stack[0] if stack else 0

