def solve(matrix):
    # Bareiss algorithm for exact integer determinant
    n = len(matrix)
    if n == 0:
        return 1
    # make a copy
    A = [row[:] for row in matrix]
    det_sign = 1
    for k in range(n-1):
        # pivot handling
        if A[k][k] == 0:
            swap = None
            for i in range(k+1, n):
                if A[i][k] != 0:
                    swap = i
                    break
            if swap is None:
                return 0
            A[k], A[swap] = A[swap], A[k]
            det_sign = -det_sign
        pivot = A[k][k]
        prev_pivot = A[k-1][k-1] if k > 0 else 1
        for i in range(k+1, n):
            for j in range(k+1, n):
                # compute exact integer
                A[i][j] = (A[i][j]*pivot - A[i][k]*A[k][j]) // prev_pivot
            # optional: set to zero for clarity
            A[i][k] = 0
    return det_sign * A[n-1][n-1]

