def solve(lst):
    """Flatten a nested list (or tuple) of integers into a flat list preserving order.
    Only list and tuple objects are treated as containers; other iterables (e.g., strings) are
    considered atomic values.
    """
    result = []
    stack = [lst]
    while stack:
        item = stack.pop()
        if isinstance(item, (list, tuple)):
            # push elements in reverse order so that leftmost is processed first
            for sub in reversed(item):
                stack.append(sub)
        else:
            result.append(item)
    return result

