    Supports '+', '-', '*', '/' operators with integer operands.
    Division truncates toward zero. Returns 0 for empty input.
    """
    if not tokens:
        return 0
    stack = []
    for tok in tokens:
        if tok in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                res = a + b
            elif tok == '-':
