def solve(matrix):
    """Return the determinant of a square integer matrix.
    Uses the Bareiss fraction-free Gaussian elimination algorithm for exact integer results.
    An empty matrix has determinant 1.
    """
    # Empty matrix case
    if not matrix:
        return 1
    n = len(matrix)
    # Ensure square
    for row in matrix:
        if len(row) != n:
            raise ValueError("Matrix must be square")
    # Copy to avoid mutating input
    A = [list(row) for row in matrix]
    if n == 1:
        return A[0][0]
    sign = 1
    prev = 1
    for k in range(n - 1):
        # Pivoting if current pivot is zero
        if A[k][k] == 0:
            for i in range(k + 1, n):
                if A[i][k] != 0:
                    A[k], A[i] = A[i], A[k]
                    sign = -sign
                    break
        pivot = A[k][k]
        # If still zero, determinant is zero
        if pivot == 0:
            return 0
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                A[i][j] = (A[i][j] * pivot - A[i][k] * A[k][j]) // prev
            A[i][k] = 0
        prev = pivot
    return sign * A[n - 1][n - 1]

