def solve(grid):
    from collections import deque
    if not grid:
        return -1
    n = len(grid)
    m = len(grid[0])
    if grid[0][0] == 1 or grid[n-1][m-1] == 1:
        return -1
    q = deque()
    q.append((0,0,0))  # steps so far
    visited = [[False]*m for _ in range(n)]
    visited[0][0] = True
    dirs = [(1,0),(-1,0),(0,1),(0,-1)]
    while q:
        i,j,d = q.popleft()
        if i == n-1 and j == m-1:
            return d
