def solve(words, width):
    # Greedy word wrap: pack as many words as possible per line separated by single spaces.
    # If a single word's length exceeds width, it occupies a line alone.
    if not words:
        return []
    lines = []
    cur_line = []
    cur_len = 0  # length of current line without spaces
    for w in words:
        if not cur_line:
            # start new line with this word
            cur_line.append(w)
            cur_len = len(w)
        else:
            # if we add a space and the word, would length be <= width?
            if cur_len + 1 + len(w) <= width:
                cur_line.append(w)
                cur_len += 1 + len(w)
            else:
                lines.append(' '.join(cur_line))
                cur_line = [w]
                cur_len = len(w)
    if cur_line:
        lines.append(' '.join(cur_line))
    return lines
